lessons.solution_code:
#include <vector>

std::vector<int> filter_evens(const std::vector<int>& numbers) {
    std::vector<int> evens;
    for (int n : numbers) {
        if (n % 2 == 0) evens.push_back(n);
    }
    return evens;
}

tests.test_code:
std::vector<int> v = {1, 2, 3, 4, 5, 6};
std::vector<int> res = filter_evens(v);
assert(res.size() == 3 && res[0] == 2 && res[2] == 6);

